mapper.select:
/*selectBuyerMdCmAdminCatalogSearch*/ SELECT A.BUYER AS BELOW_COMORG_CODE, DECODE(A.BUYER,'KRDOOD0001','창원','KRDOOS0004','서울') AS COM_NAME, A.CONTRACT_NO AS CONTRACT_NO, A.CONTRACT_SEQ AS CONTRACT_SEQ, B.CATEGORY_NO AS CATEGORY_NO, B.CATEGORY_TEXT AS CATEGORY_TEXT, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, DECODE(B.PRODUCT_CLOSE_FLAG,'N','단가계약품목','A','일회성_미발주','C','신규요청품목','Y','단종') AS ITEM_NO_NAME, A.DESCRIPTION AS DESCRIPTION, A.SPECIFICATION AS SPECIFICATION, A.UNIT_MEASURE AS UNIT_MEASURE, A.LIST_PRICE AS LIST_PRICE, A.UNIT_PRICE AS UNIT_PRICE, B.MAKER_CODE AS MAKER_CODE, B.MAKER_NAME AS MAKER_NAME, A.MAKER_PART_NO AS MAKER_PART_NO, B.DELIVERY_LT AS DELIVERY_LT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = A.ORIGIN_CODE) AS ORIGIN_NAME, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AS AGENT_NAME, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = A.PROCESS_TYPE) AS PROCESS_TYPE, A.AGENT AS AGENT_CODE, A.BUYER AS BUYER, A.ITEM_NO AS ITEM_NO FROM ICOMCQDT A, ICOMBYIT B WHERE A.BUYER = B.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER = #{st_buyer_code} AND A.STATUS <> 'D' AND B.STATUS <> 'D'
AND A.BUYER_ITEM_NO LIKE UPPER ('%'||#{st_search_no}||'%')
AND A.DESCRIPTION LIKE UPPER ('%'||#{st_description}||'%')
AND A.SPECIFICATION LIKE UPPER ('%'||#{st_specifcation}||'%')
AND A.AGENT = #{st_agent}
AND B.PRODUCT_CLOSE_FLAG = #{st_item_gubun}
ORDER BY 1,7
